 for x in range(80,181,5):
  xx=x*scale; d.line((xx,0,xx,1152),fill=(20,20,20));
  if x%10==0:d.text((xx+2,2),str(x),fill='black')
 for y in range(50,111,5):
  yy=y*scale; d.line((0,yy,2048,yy),fill=(20,20,20));
  if y%10==0:d.text((2,yy+2),str(y),fill='black')
 im.crop((80*scale,50*scale,181*scale,111*scale)).save(f'.tmp/grid5_{i}.png')
